#include <stdio.h>

int main() {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    char mapa[105][105];
    int start_r = -1, start_c = -1;

    for (int i = 0; i < L; i++) {
        scanf("%s", mapa[i]);
        if (start_r == -1) {
            for (int j = 0; j < C; j++) {
                if (mapa[i][j] == 'o') {
                    start_r = i;
                    start_c = j;
                }
            }
        }
    }

    int cur_r = start_r;
    int cur_c = start_c;

    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    while (1) {
        int next_r = -1, next_c = -1;
        for (int i = 0; i < 4; i++) {
            int nr = cur_r + dr[i];
            int nc = cur_c + dc[i];
            if (nr >= 0 && nr < L && nc >= 0 && nc < C) {
                if (mapa[nr][nc] == 'H') {
                    next_r = nr;
                    next_c = nc;
                    break;
                }
            }
        }

        if (next_r == -1) {
            break;
        }

        mapa[cur_r][cur_c] = '.';
        cur_r = next_r;
        cur_c = next_c;
    }

    printf("%d %d\n", cur_r + 1, cur_c + 1);

    return 0;
}
